<script module lang="ts">
/**
 * An Input preset for passwords, with a reveal toggle (`design/components/password-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/password-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { Icon, agentMember, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/password-input.module.css'
import Input from './Input.svelte'

export interface PasswordInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Has a default, unlike Input's plain passthrough, because a password field without one breaks
   * password managers and WCAG 1.3.5. Sign-up flows pass `'new-password'`. Other values belong
   * to other members (one-time codes use OTPInput).
   */
  autoComplete?: 'current-password' | 'new-password'
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  name?: string
  onChange?: (value: string, event: Event) => void
  placeholder?: string
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * The toggle's accessible name ("Show password"). The member has no built-in text.
   */
  toggleLabel: string
  value?: string
}
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  autoComplete = 'current-password',
  defaultValue,
  disabled = false,
  id: idOwn,
  invalid: invalidOwn = false,
  name,
  onChange,
  placeholder,
  readOnly = false,
  size = 'md',
  toggleLabel,
  value,
}: PasswordInputProps = $props()
const joined = joinSlot(undefined, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
let revealed = $state(false)
let held = $state({
  start: null as number | null,
  end: null as number | null,
  direction: 'none' as 'forward' | 'backward' | 'none',
})
let frame = $state<HTMLElement | null>(null)
const field = $derived(frame?.querySelector('input') ?? null)
const effect1 = () => {
  ;(field?.setAttribute('spellcheck', 'false'),
    field?.setAttribute('autocapitalize', 'off'),
    field?.setAttribute('autocorrect', 'off'))
}
watchEffect(effect1)
const effect2 = () => {
  held.start !== null &&
    held.end !== null &&
    (field?.setSelectionRange(held.start, held.end, held.direction),
    requestAnimationFrame(() => field?.setSelectionRange(held.start, held.end, held.direction)))
}
watchEffect(effect2, { watch: () => revealed, mount: false })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'PasswordInput',
    element: () => frame?.querySelector('input'),
    state: () => ({
      value: frame?.querySelector('input')?.value ?? '',
      revealed: revealed,
      disabled: disabled,
      invalid: invalid,
      readonly: readOnly,
    }),
    actions: {},
    secret: ['value'],
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span
    bind:this={frame}
    class={styles.password}
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-readonly={(readOnly) ? '' : undefined}
    data-state={revealed ? 'visible' : 'hidden'}
    data-member="password-input"
    >{#snippet trailingOfInput1()
      }<button
        class={styles.toggle}
        type="button"
        {disabled}
        aria-pressed={revealed}
        aria-label={toggleLabel}
        onclick={() => { (held = { start: field?.selectionStart ?? null, end: field?.selectionEnd ?? null, direction: field?.selectionDirection ?? 'none' }, revealed = !revealed) }}
        >{#if revealed}<Icon name="hidden" {size} />{:else}<Icon name="visible" {size} />{/if
      }</button
    >{/snippet
    }<Input
      type={revealed ? 'text' : 'password'}
      {value}
      {defaultValue}
      {placeholder}
      {size}
      {disabled}
      {readOnly}
      {invalid}
      {autoComplete}
      {name}
      {id}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      aria-describedby={ariaDescribedby}
      aria-required={ariaRequired}
      onChange={(next, event) => onChange?.(next, event)}
      trailing={trailingOfInput1}
  /></span
>{/if
}{@render joined.end?.()}
